opt_peep(opt_state_t *opt_state, struct block *b)
{
        struct slist *s;
        struct slist *next, *last;
        int val;

        s = b->stmts;
        if (s == 0)
                return;

        last = s;
        for (/*empty*/; /*empty*/; s = next) {
                /*
                 * Skip over nops.
                 */
                s = this_op(s);
                if (s == 0)
                        break;  /* nothing left in the block */

                /*
                 * Find the next real instruction after that one
                 * (skipping nops).
                 */
                next = this_op(s->next);
                if (next == 0)
                        break;  /* no next instruction */
                last = next;

                /*
                 * st  M[k]     -->     st  M[k]
                 * ldx M[k]             tax
                 */
                if (s->s.code == BPF_ST &&
                    next->s.code == (BPF_LDX|BPF_MEM) &&
                    s->s.k == next->s.k) {
                        opt_state->done = 0;
                        next->s.code = BPF_MISC|BPF_TAX;
                }
                /*
                 * ld  #k       -->     ldx  #k
                 * tax                  txa
                 */
                if (s->s.code == (BPF_LD|BPF_IMM) &&
                    next->s.code == (BPF_MISC|BPF_TAX)) {
                        s->s.code = BPF_LDX|BPF_IMM;
                        next->s.code = BPF_MISC|BPF_TXA;
                        opt_state->done = 0;
                }
                /*
                 * This is an ugly special case, but it happens
                 * when you say tcp[k] or udp[k] where k is a constant.
                 */
                if (s->s.code == (BPF_LD|BPF_IMM)) {
                        struct slist *add, *tax, *ild;

                        /*
                         * Check that X isn't used on exit from this
                         * block (which the optimizer might cause).
                         * We know the code generator won't generate
                         * any local dependencies.
                         */
                        if (ATOMELEM(b->out_use, X_ATOM))
                                continue;

                        /*
                         * Check that the instruction following the ldi
                         * is an addx, or it's an ldxms with an addx
                         * following it (with 0 or more nops between the
                         * ldxms and addx).
                         */
                        if (next->s.code != (BPF_LDX|BPF_MSH|BPF_B))
                                add = next;
                        else
                                add = this_op(next->next);
                        if (add == 0 || add->s.code != (BPF_ALU|BPF_ADD|BPF_X))
                                continue;

                        /*
                         * Check that a tax follows that (with 0 or more
                         * nops between them).
                         */
                        tax = this_op(add->next);
                        if (tax == 0 || tax->s.code != (BPF_MISC|BPF_TAX))
                                continue;

                        /*
                         * Check that an ild follows that (with 0 or more
                         * nops between them).
                         */
                        ild = this_op(tax->next);
                        if (ild == 0 || BPF_CLASS(ild->s.code) != BPF_LD ||
                            BPF_MODE(ild->s.code) != BPF_IND)
                                continue;
                        /*
                         * We want to turn this sequence:
                         *
                         * (004) ldi     #0x2           {s}
                         * (005) ldxms   [14]           {next}  -- optional
                         * (006) addx                   {add}
                         * (007) tax                    {tax}
                         * (008) ild     [x+0]          {ild}
                         *
                         * into this sequence:
                         *
                         * (004) nop
                         * (005) ldxms   [14]
                         * (006) nop
                         * (007) nop
                         * (008) ild     [x+2]
                         *
                         * XXX We need to check that X is not
                         * subsequently used, because we want to change
                         * what'll be in it after this sequence.
                         *
                         * We know we can eliminate the accumulator
                         * modifications earlier in the sequence since
                         * it is defined by the last stmt of this sequence
                         * (i.e., the last statement of the sequence loads
                         * a value into the accumulator, so we can eliminate
                         * earlier operations on the accumulator).
